.related-courses {
    margin: 0;
    display: flex;
    flex-direction: row;
    list-style-type: none;
    max-width: initial;
    gap: $measure--small1;

    @include media('<tablet') {
        flex-direction: column;
    }
}

.rel-course-card-v26 {
    flex: 1;
}

.rel-course-card-v26__anchor {
    border-radius: $measure--quarter;
    background: $color-purewhite;
    display: flex;
    height: 100%;
    padding: $measure--small1;
    color: $color-nearblack;
    border-bottom: none;

    &:visited {
        color: initial;
    }
}

.rel-course-card-v26__heading {
    margin-top: 0;
}

.rel-course-card-v26____type {
    @include smalltype();
    color: $color-gray6;
}

.rel-course-card-v26____tag {
    @include smalltype();
    font-weight: $font-weight-medium;
}

.rel-course-card-v26____description {
    display: none;
}
